def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    motif=[grid[r][w-1] for r in range(1,4)]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==6:
                for k,color in enumerate(motif):
                    rr=r+k-1
                    if 0<=rr<h: out[rr][c]=color
